class Solution {
public:
    int minimumOperationsToMakeKPeriodic(string word, int k) {
        int n = word.size();
        unordered_map<string, int> counts;
        int max_freq = 0;
        for (int i = 0; i < n; i += k) {
            string sub = word.substr(i, k);
            counts[sub]++;
            max_freq = max(max_freq, counts[sub]);
        }
        return (n / k) - max_freq;
    }
};

class Solution {
    public int minimumOperationsToMakeKPeriodic(String word, int k) {
        int n = word.length();
        Map<String, Integer> counts = new HashMap<>();
        int maxFreq = 0;
        for (int i = 0; i < n; i += k) {
            String sub = word.substring(i, i + k);
            int count = counts.getOrDefault(sub, 0) + 1;
            counts.put(sub, count);
            maxFreq = Math.max(maxFreq, count);
        }
        return (n / k) - maxFreq;
    }
}

var minimumOperationsToMakeKPeriodic = function(word, k) {
    const n = word.length;
    const counts = new Map();
    let maxFreq = 0;
    for (let i = 0; i < n; i += k) {
        const sub = word.slice(i, i + k);
        const count = (counts.get(sub) || 0) + 1;
        counts.set(sub, count);
        if (count > maxFreq) maxFreq = count;
    }
    return Math.floor(n / k) - maxFreq;
};
